// Host-only extension. Device computation is generated by NineToothed.
#include "core_ninetoothed_bridge.cpp"

namespace rms3d_adapter {
static RmsFn functions[5]{};
static std::atomic<uint64_t> calls{0}, fallbacks{0};
struct Planned {
    graph::GraphTensor out, x, weight;
    double epsilon;
    RmsFn function;
    void *fallback;
};

void *plan(Tensor out, const Tensor &x, const Tensor &weight, float epsilon) {
    int index = -1;
    if (x->dtype() == DataType::F16) index = weight->dtype() == DataType::F16 ? 0 : weight->dtype() == DataType::F32 ? 1 : -1;
    if (x->dtype() == DataType::BF16) index = weight->dtype() == DataType::BF16 ? 2 : weight->dtype() == DataType::F32 ? 3 : -1;
    if (x->dtype() == DataType::F32 && weight->dtype() == DataType::F32) index = 4;
    bool supported = index >= 0 && functions[index] && x->ndim() == 3 && x->size(2) == 128
        && x->size(0) > 0 && x->size(1) > 0
        && weight->ndim() == 1 && weight->size(0) == 128 && out->shape() == x->shape()
        && out->dtype() == x->dtype() && std::isfinite(epsilon) && epsilon > 0;
    // Positive nonoverlapping row-major views include actual QKV narrow slices.
    // Unsupported layouts keep the original API's own validation and fallback.
    if (supported) {
        for (const auto &tensor : {x, out}) {
            supported = supported && tensor->stride(2) > 0
                && tensor->stride(1) >= static_cast<Stride>(128) * tensor->stride(2)
                && tensor->stride(0) >= static_cast<Stride>(tensor->size(1)) * tensor->stride(1);
        }
        supported = supported && weight->stride(0) > 0;
    }
    return new Planned{graph::GraphTensor(out), graph::GraphTensor(x), graph::GraphTensor(weight),
                       epsilon, supported ? functions[index] : nullptr,
                       supported ? nullptr : rms_adapter::plan(out, x, weight, epsilon)};
}

void run(void *metadata) {
    auto *p = static_cast<Planned *>(metadata);
    if (p->function) {
        NativeTensor epsilon{&p->epsilon, nullptr, nullptr};
        check(p->function(context::getStream(), view(p->x), view(p->weight), epsilon, view(p->out)));
        ++calls;
    } else {
        rms_adapter::run(p->fallback);
        ++fallbacks;
    }
}

void cleanup(void **metadata) {
    auto *p = static_cast<Planned *>(*metadata);
    if (!p->function) rms_adapter::cleanup(&p->fallback);
    delete p;
    *metadata = nullptr;
}
}

extern "C" void songshan3_register_rms3d(void *f16_f16, void *f16_f32, void *bf16_bf16, void *bf16_f32, void *f32_f32) {
    auto device = Device::Type::HYGON;
    if (!rms_adapter::base_plan) {
        rms_adapter::base_plan = op::RMSNorm::plan_dispatcher().lookup(device);
        rms_adapter::base_run = op::RMSNorm::run_dispatcher().lookup(device);
        rms_adapter::base_cleanup = op::RMSNorm::cleanup_dispatcher().lookup(device);
    }
    void *values[] = {f16_f16, f16_f32, bf16_bf16, bf16_f32, f32_f32};
    for (int i = 0; i < 5; ++i) rms3d_adapter::functions[i] = reinterpret_cast<RmsFn>(values[i]);
    op::RMSNorm::plan_dispatcher().registerDevice(device, &rms3d_adapter::plan);
    op::RMSNorm::run_dispatcher().registerDevice(device, &rms3d_adapter::run);
    op::RMSNorm::cleanup_dispatcher().registerDevice(device, &rms3d_adapter::cleanup);
}

extern "C" uint64_t songshan3_rms3d_count(int fallback) {
    return fallback ? rms3d_adapter::fallbacks.load() : rms3d_adapter::calls.load();
}
